.results{background:#f8e4c7}.results h2{font:600 clamp(2.4rem,5vw,4.4rem)/1 var(--display);letter-spacing:-.05em;margin:12px 0}.results .sub{max-width:600px;color:#485d58}.podium{list-style:none;padding:0;counter-reset:rank;margin:30px 0}.podium li{counter-increment:rank;display:grid;grid-template-columns:43px 1fr auto;gap:12px;align-items:center;border-bottom:1px solid #bcac8f;padding:13px 4px}.podium li:before{content:counter(rank,decimal-leading-zero);font:12px var(--mono);color:#a15241}.podium li:first-child{background:var(--gold);margin:0 -12px;padding:17px 16px;border:1px solid var(--ink);box-shadow:4px 4px 0 var(--ink)}.podium strong{font:600 clamp(18px,3vw,27px) var(--display);overflow-wrap:anywhere}.podium span{font:11px var(--mono)}.results-actions{display:flex;gap:15px;flex-wrap:wrap}.footnote{font:12px var(--mono);line-height:1.8;max-width:730px;margin:48px auto 0;text-align:center;color:#4a645f}.footnote a{text-decoration-thickness:1px;text-underline-offset:3px}.stamp{display:inline-block;border:1px solid #a89368;padding:2px 7px;transform:rotate(-3deg);margin:0 6px}.reveal{animation:rise .45s both}@keyframes rise{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:translateY(0)}}@media(max-width:740px){.shell{padding:0 18px}.serial{font-size:9px}.hero-grid{grid-template-columns:1fr;gap:0}.hero-copy{padding:40px 0 10px}.hero-image{height:240px;margin:6px 0 0;transform:rotate(1deg);border-width:6px}.caption{padding:16px 0 25px}.intro{grid-template-columns:1fr;gap:10px}main{padding-top:35px}.battle-grid{grid-template-columns:1fr 46px 1fr}.choice{min-height:210px;padding:15px;box-shadow:3px 3px 0 var(--ink)}.choice strong{font-size:clamp(1.22rem,4vw,1.8rem)}.choice small,.choice span:last-child{font-size:10px}.versus{font-size:18px}.podium{margin:20px 0}.podium li{grid-template-columns:30px 1fr auto}.podium span{font-size:9px}}@media(max-width:390px){.battle-grid{grid-template-columns:1fr 25px 1fr}.choice{padding:12px}.choice strong{font-size:1.25rem}.versus{font-size:14px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
