<header class="topbar"><div class="shell"><a class="brand" href="index.php">← Chloe Reads Jon</a><span class="serial">FIELD NOTES / NO. 2013·06</span></div></header>
<section class="hero"><div class="shell"><div class="hero-grid"><div class="hero-copy"><div class="eyebrow">A tiny tournament of preferences</div><h1>Two<br><em>good</em> things.</h1><p class="lead">When everything sounds lovely, don't choose from a list. Put two ideas on the table and see which one makes you smile more.</p></div><img class="hero-image" src="two-good-things.webp" alt="Illustrated tabletop with a little toy car and a forest trail on two opposing tickets" loading="eager"></div><div class="caption">01 / THE QUESTION IS NOT “WHAT IS BEST?” BUT “WHICH WOULD WE LOVE MORE?”</div></div></section>
<main class="shell"><div class="intro"><div><div class="section-tag">The experiment / 01</div><h2>Make the difficult choice delightfully small.</h2></div><p>Inspired by Jon's pair-at-a-time ranking idea. Give your contenders a fair little tournament; the scoreboard emerges one choice at a time. No account, no data sent anywhere.</p></div>
<section id="setup" class="setup reveal" aria-label="Set up a tournament"><div class="section-tag">Choose your contenders</div><div class="presets"><button type="button" class="chip active" data-preset="adventures">Weekend adventures</button><button type="button" class="chip" data-preset="making">Things to make</button><button type="button" class="chip" data-preset="custom">My own list</button></div><label for="entries">One possibility per line (2–12)</label><textarea id="entries" spellcheck="false"></textarea><div class="setup-foot"><div class="hint">Each pair meets once. With six ideas, that's 15 tiny decisions. Choose with your gut; you can undo.</div><button type="button" id="start" class="primary">Start the tournament ↗</button></div><p id="error" class="error" role="alert"></p></section>
<section id="arena" class="arena hidden" aria-live="polite"><div class="battle-header"><div><div class="section-tag">The face-off / 02</div><h2 style="font:600 clamp(1.8rem,4vw,3rem) var(--display);margin:8px 0 0">Which one wins today?</h2></div><span id="count" class="serial" style="color:var(--ink)"></span></div><div class="meter" role="progressbar" aria-label="Tournament progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" id="meter"><i id="fill"></i></div><div class="battle-grid"><button class="choice" type="button" id="left"><small>Option A · J</small><strong id="leftText"></strong><span>Pick this one ↗</span></button><div class="versus" aria-hidden="true">or</div><button class="choice" type="button" id="right"><small>Option B · L</small><strong id="rightText"></strong><span>Pick this one ↗</span></button></div><div class="arena-foot"><p id="status">A preference is not a promise. Just pick what feels right.</p><div><button class="mini" id="undo" type="button">↶ Undo</button><button class="mini" id="restart" type="button">Start over</button></div></div></section>
<section id="results" class="results hidden"><div class="section-tag">The reveal / 03</div><h2>Your little league table.</h2><p class="sub">Not a verdict from the universe. Just a map of what you kept choosing when the choices got real.</p><ol id="podium" class="podium"></ol><div class="results-actions"><button class="primary" id="copy" type="button">Copy the ranking ↗</button><button class="secondary" id="again" type="button">Run it again</button><button class="secondary" id="resultUndo" type="button">↶ Undo last choice</button></div><p id="copyStatus" class="hint" role="status" style="margin:18px 0 0"></p></section>
<p class="footnote"><span class="stamp">WHY THIS EXISTS</span> Inspired by Jon's <a href="https://jona.ca/2013/06/elo-preference-ranker.html" target="_blank" rel="noopener noreferrer">Elo Preference Ranker</a>, where he used head-to-head choices to discover what mattered most. This is a playful family-sized reinterpretation. Scores stay in this browser.</p></main>
<script>
(()=>{'use strict';const $=id=>document.getElementById(id),presets={adventures:['Build a model together','Go for a forest walk','Play a co-op video game','Explore a museum','Bake ridiculous cookies','Take a scenic drive'],making:['Build a cardboard city','Make a tiny comic book','Design a fantasy map','Film a stop-motion chase','Invent a board game','Build a model spaceship']};let state=null;const key='two-good-things-v1';function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch(e){}}function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}function choosePreset(which){document.querySelectorAll('.chip').forEach(b=>b.classList.toggle('active',b.dataset.preset===which));if(which!=='custom')$('entries').value=presets[which].join('\n');else $('entries').value='';$('error').textContent='';$('entries').focus()}function ratings(){let scores=state.items.map(()=>1000);for(const {pair,winner} of state.picks){const [a,b]=state.pairs[pair],ea=1/(1+10**((scores[b]-scores[a])/400)),eb=1-ea;scores[a]+=32*((winner===a?1:0)-ea);scores[b]+=32*((winner===b?1:0)-eb)}return scores}function render(){const n=state.picks.length,total=state.pairs.length,done=n===total;$('setup').classList.add('hidden');$('arena').classList.toggle('hidden',done);$('results').classList.toggle('hidden',!done);if(!done){const [a,b]=state.pairs[n];$('leftText').textContent=state.items[a];$('rightText').textContent=state.items[b];$('count').textContent=(n+1)+' / '+total;$('fill').style.width=(n/total*100)+'%';$('meter').setAttribute('aria-valuenow',Math.round(n/total*100));$('undo').disabled=n===0;$('status').textContent=n===0?'A preference is not a promise. Just pick what feels right.':(total-n)+' matchups left. Your instincts are doing the sorting.'}else{const scores=ratings();const order=state.items.map((name,i)=>({name,score:scores[i],i})).sort((a,b)=>b.score-a.score||a.i-b.i);$('podium').replaceChildren(...order.map((x,i)=>{const li=document.createElement('li'),strong=document.createElement('strong'),span=document.createElement('span');strong.textContent=x.name;span.textContent=i===0?'THE CHAMPION':Math.round(x.score)+' PTS';li.append(strong,span);return li}));$('copyStatus').textContent=''}save();(done?$('results'):$('arena')).scrollIntoView({behavior:'smooth',block:'start'})}function pick(side){if(!state||state.picks.length>=state.pairs.length)return;const index=state.picks.length;state.picks.push({pair:index,winner:state.pairs[index][side]});render()}function undo(){if(!state||!state.picks.length)return;state.picks.pop();render()}function reset(){state=null;try{localStorage.removeItem(key)}catch(e){}$('arena').classList.add('hidden');$('results').classList.add('hidden');$('setup').classList.remove('hidden');$('setup').scrollIntoView({behavior:'smooth'})}document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>choosePreset(b.dataset.preset));$('entries').addEventListener('input',()=>{document.querySelectorAll('.chip').forEach(b=>b.classList.toggle('active',b.dataset.preset==='custom'));$('error').textContent=''});$('start').onclick=()=>{const raw=$('entries').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean),items=[...new Map(raw.map(s=>[s.toLocaleLowerCase(),s])).values()];if(items.length<2||items.length>12){$('error').textContent='Please enter 2 to 12 distinct ideas (one per line).';return}const pairs=[];for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++)pairs.push([i,j]);state={items,pairs:shuffle(pairs),picks:[]};render()};$('left').onclick=()=>pick(0);$('right').onclick=()=>pick(1);$('undo').onclick=undo;$('resultUndo').onclick=undo;$('restart').onclick=reset;$('again').onclick=reset;$('copy').onclick=async()=>{const scores=ratings(),sorted=state.items.map((name,i)=>({name,score:scores[i]})).sort((a,b)=>b.score-a.score),out='Two Good Things — my ranking\n'+sorted.map((x,i)=>(i+1)+'. '+x.name).join('\n');try{await navigator.clipboard.writeText(out);$('copyStatus').textContent='Ranking copied. The champion may now be announced with appropriate ceremony.'}catch(e){$('copyStatus').textContent='Clipboard unavailable here; you can select the ranking above.'}};document.addEventListener('keydown',e=>{if(!state||state.picks.length===state.pairs.length||/INPUT|TEXTAREA/.test(document.activeElement.tagName)||e.altKey||e.metaKey||e.ctrlKey)return;if(e.key.toLowerCase()==='j')pick(0);if(e.key.toLowerCase()==='l')pick(1)});$('entries').value=presets.adventures.join('\n');try{const s=JSON.parse(localStorage.getItem(key));if(s&&Array.isArray(s.items)&&s.items.length>=2&&s.items.length<=12&&Array.isArray(s.pairs)&&s.pairs.length===s.items.length*(s.items.length-1)/2&&Array.isArray(s.picks)&&s.picks.length<=s.pairs.length){state=s;$('entries').value=s.items.join('\n');render()}}catch(e){}
})();
</script>
</body></html>
